/* =====================================================================
   tiny helpers
   ===================================================================== */
function h(tag, a = {}, ...kids) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(a || {})) {
    if (v === false || v == null) continue;
    if (k === 'class') e.className = v;
    else if (k === 'style' && typeof v === 'object') { for (const [p, q] of Object.entries(v)) e.style.setProperty(p, q); }
    else if (k.startsWith('on') && typeof v === 'function') e.addEventListener(k.slice(2), v);
    else if (k === 'value') e.value = v;
    else if (k === 'checked' || k === 'selected' || k === 'disabled' || k === 'multiple') e[k] = !!v;
    else e.setAttribute(k, v === true ? '' : v);
  }
  for (const c of kids.flat(4)) { if (c == null || c === false) continue; ap(e, c.nodeType ? c : document.createTextNode(String(c))); }
  return e;
}
/** append that skips null/false and flattens arrays */
function ap(el, ...kids) { for (const c of kids.flat(4)) { if (c == null || c === false) continue; el.append(c.nodeType ? c : document.createTextNode(String(c))); } return el; }
const arr = (v) => (v == null || v === '' ? [] : Array.isArray(v) ? v : [v]);
const initials = (n) => String(n).replace(/^(The|Old|Ser|Lady|Lord)\s+/, '').split(/\s+/).map((w) => w[0] || '').join('').slice(0, 2).toUpperCase();
const hashHue = (s) => { let x = 0; for (const c of String(s)) x = (x * 31 + c.charCodeAt(0)) % 360; return x; };
const fmtN = (n) => Number(n || 0).toLocaleString();
const toast = (m) => new Notice(m);
const pick = (a) => a[Math.floor(Math.random() * a.length)];
const byName = (a, b) => a.basename.localeCompare(b.basename);
const clone = (o) => JSON.parse(JSON.stringify(o));
const todayISO = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; };
const safeName = (s) => String(s).replace(/[\\/:*?"<>|#^[\]]/g, '').trim();
const lines = (s) => String(s || '').split('\n').map((x) => x.trim()).filter(Boolean);

/** "[[Path/Name#h|Alias]]" | "Name" → "Path/Name" */
function linkName(v) {
  if (v == null) return '';
  if (typeof v === 'object') return v.path || v.name || '';
  const s = String(v).trim();
  const m = s.match(/^!?\[\[([^\]|#]+)(?:#[^\]|]*)?(?:\|[^\]]*)?\]\]$/);
  return (m ? m[1] : s).trim();
}
const names = (v) => arr(v).map(linkName).filter(Boolean);
const display = (n) => String(n).split('/').pop().replace(/\.md$/, '');

